function gameArtwork(g){return `<div class="game-art${g.id==='zombie'?' game-art-soon':''}"><img src="/assets/${g.image}" srcset="/assets/${g.image.replace('-900.webp','-450.webp')} 450w, /assets/${g.image} 900w" sizes="(max-width: 640px) calc(100vw - 40px), (max-width: 850px) calc((100vw - 70px) / 2), calc((100vw - 120px) / 3)" alt="Обложка ${esc(g.title)}" loading="lazy" decoding="async" width="900" height="506">${g.id==='zombie'?'<span class="game-coming-label">СКОРО НА НАШЕЙ АРЕНЕ</span>':''}</div>`}
const gameSummaries={teamforce:'Командная перестрелка: захватывайте точки и прикрывайте друг друга.',elevators:'Сражайтесь на шести этажах. Перемещайтесь на лифтах и меняйте тактику.',portals:'Командные бои с порталами и телепортами между этажами.',starforce:'Космическая арена с телепортами и большим пространством для манёвров.',minigames:'Три семейные мини-игры с простыми правилами. Подойдут для первого знакомства с VR.',zombie:'Командой отбивайтесь от волн зомби. Скоро на нашей арене.'};
function gameCard(g){return `<button class="game-card" data-action="story" data-id="${g.id}" aria-label="${g.video?'Смотреть обзор':'Подробнее об игре'} ${esc(g.title)}"><div class="game-cover">${gameArtwork(g)}<span class="game-video-label">${g.video?icon('play')+' Видеообзор':'Подробнее'} ${icon('arrow')}</span></div><div class="game-copy"><span class="game-genre">${g.genre}</span><h3>${g.title}</h3><p>${gameSummaries[g.id]||g.description}</p><div class="game-meta"><span>${g.players}</span><span>${g.age||g.mode}</span></div></div></button>`}
function gamesSection(){return `<section class="section games-section" id="games"><div class="wrap"><div class="eyebrow">Выбери свою вселенную</div><div class="section-head"><h2>КАЖДАЯ ИГРА —<br><em>ОТДЕЛЬНЫЙ МИР</em></h2><p class="games-sub">Смотри видеообзоры, выбирай сценарий<br>и собирай свою команду</p></div><div class="filters" role="group" aria-label="Категории игр"><button class="filter active" data-filter="all" aria-pressed="true">Все игры</button><button class="filter" data-filter="team" aria-pressed="false">Командные</button><button class="filter" data-filter="kids" aria-pressed="false">Для всей семьи</button></div><div class="game-grid" id="game-grid">${games.map(gameCard).join('')}</div><div class="game-foot"><span>${icon('info')}Поможем выбрать сценарий по возрасту и настроению</span><button class="text-link" style="background:none;border-width:0 0 1px" data-action="callback">Помогите выбрать ${icon('arrow')}</button></div></div></section>`}
function eventsSection(){return `<section class="section events-section" id="events"><div class="wrap"><div class="section-head"><div><div class="eyebrow">Для вашей компании</div><h2>ПРАЗДНИК <em>БЕЗ ГРАНИЦ</em></h2></div></div><div class="events-grid"><a class="event-card" href="/birthday/"><img class="event-bg" src="/assets/birthday-party.webp" srcset="/assets/birthday-party-768.webp 768w, /assets/birthday-party.webp 1448w" sizes="(max-width: 640px) calc(100vw - 40px), calc((100vw - 94px) / 2)" alt="" loading="lazy" decoding="async" width="1448" height="1086"><span class="tag">ОТ 7 ЛЕТ · ДО 10 ИГРОКОВ</span><h3>День рождения<br>на VR-арене</h3><p>Играйте с друзьями, а после — торт и подарки в лаунж-зоне.</p><span class="text-link">О празднике</span></a><a class="event-card" href="/corporate/"><img class="event-bg" src="/assets/corporate-team.webp" srcset="/assets/corporate-team-768.webp 768w, /assets/corporate-team.webp 1448w" sizes="(max-width: 640px) calc(100vw - 40px), calc((100vw - 94px) / 2)" alt="" loading="lazy" decoding="async" width="1448" height="1086"><span class="tag">ДЛЯ КОЛЛЕГ И ДРУЗЕЙ</span><h3>Корпоратив<br>в другой реальности</h3><p>Командные игры и время для общения. Вся арена — для вас.</p><span class="text-link">О корпоративе</span></a></div></div></section>`}
const eventRates={60:[10000,null],120:[12000,16000],180:[17000,23000]};
const gameRates=[900,1200],privateRates=[8000,11000];
const privatePackageRates={60:privateRates,120:[10000,14000],180:[15000,20000]};
function priceSpecs(kind='home'){
 const eventFeatures=['До 10 игроков','Арена и лаунж-зона','Фото и видео'];
 if(kind==='home')return [
  {title:'Игра',time:'1 час',duration:'60',rates:gameRates,per:'за 1 игрока',format:'game',symbol:'headset',description:'Игры на выбор. Могут присоединиться другие игроки.'},
  {title:'Команда',time:'1 час',duration:'60',rates:privateRates,per:'за компанию',format:'private',symbol:'users',description:'Арена только для вашей компании. До 10 игроков на площадке. Фото и видео.'},
  {title:'Праздник базовый',time:'2 часа',duration:'120',featured:true,rates:eventRates[120],per:'за компанию',format:'birthday',symbol:'gift',description:'Закрытая арена, лаунж-зона, подбор игр, инструктаж, фото и видео.'},
  {title:'Праздник максимум',time:'3 часа',duration:'180',rates:eventRates[180],per:'за компанию',format:'birthday',symbol:'trophy',description:'Хватит времени на игры и отдых. Закрытая арена, лаунж-зона, подбор игр, инструктаж, фото и видео.'}
 ];
 return [
  {title:'Праздник базовый',subtitle:'Игры и отдых в одном пакете',time:'2 ЧАСА',duration:'120',featured:true,features:eventFeatures},
  {title:'Праздник максимум',subtitle:'Больше времени на игры и общение',time:'3 ЧАСА',duration:'180',features:eventFeatures}
 ].map(p=>({...p,rates:eventRates[p.duration],per:'за компанию',format:kind==='corporate'?'corporate':'birthday',button:'Выбрать пакет'}));
}
function tariffTable(){return `<div class="tariff-table-wrap"><table class="tariff-table"><caption class="sr-only">Стоимость игры и праздников в будни и выходные</caption><thead><tr><th scope="col">Формат</th><th scope="col">Длительность</th><th scope="col">ПН–ЧТ</th><th scope="col">ПТ–ВС</th><th scope="col">Что входит</th><th scope="col"><span class="sr-only">Запись</span></th></tr></thead><tbody>${priceSpecs().map(p=>`<tr${p.featured?' class="tariff-recommended"':''}><th scope="row"><div class="tariff-name">${icon(p.symbol)}<div><h3>${p.title}</h3>${p.featured?`<span class="tariff-recommendation">${icon('star')}Оптимальный вариант</span>`:''}<span>${p.per}</span></div></div></th><td class="tariff-duration" data-label="Длительность">${p.time}</td><td class="tariff-price" data-label="ПН–ЧТ">${money(p.rates[0])}</td><td class="tariff-price" data-label="ПТ–ВС">${money(p.rates[1])}</td><td class="tariff-includes">${p.description}</td><td class="tariff-action"><button class="btn btn-outline" data-book data-format="${p.format}" data-duration="${p.duration}" data-package="${p.title}" aria-label="Выбрать формат ${p.title}">Выбрать</button></td></tr>`).join('')}</tbody></table></div>`}
function priceCards(kind='birthday'){return priceSpecs(kind).map(p=>`<article class="price-card ${p.featured?'featured':''}"><div class="price-card-top"><div class="eyebrow">${p.time}</div>${p.featured?`<span class="tariff-recommendation">${icon('star')}Оптимальный вариант</span>`:''}</div><h3>${p.title}</h3><p class="price-desc">${p.subtitle}</p><div class="price-rates">${p.rates.map((price,i)=>`<div class="price-rate"><span>${i?'ПТ–ВС':'ПН–ЧТ'}</span><strong>${money(price)}</strong></div>`).join('')}<small>${p.per}</small></div><ul>${p.features.map(f=>`<li>${icon('check')}<span>${f}</span></li>`).join('')}</ul><button class="btn ${p.featured?'':'btn-outline'}" data-book data-format="${p.format}" data-duration="${p.duration}" data-package="${p.title}">${p.button}</button></article>`).join('')}
function pricing(kind='home',sectionId='prices'){const event=kind!=='home';return `<section class="section prices-section" id="${sectionId}"><div class="wrap"><div class="eyebrow">${event?'Игры и отдых для вашей компании':'Найди свой формат'}</div><div class="section-head"><h2>${event?'ВЫБЕРИ ПАКЕТ<br><em>ДЛЯ ВАШЕГО ПРАЗДНИКА</em>':'СКОЛЬКО СТОИТ<br><em>ДРУГАЯ РЕАЛЬНОСТЬ?</em>'}</h2><p class="section-intro">${event?'Арена и лаунж-зона только для вас.<br>Цены за компанию до 10 игроков.':'Сравни четыре формата. <br>Цены будней и выходных — рядом.'}</p></div>${event?`<div class="price-grid price-grid-event" id="${sectionId}-grid">${priceCards(kind)}</div><div class="package-included"><h3>В каждом пакете</h3><p class="package-summary">Подбор игр, инструктаж, персональный инструктор и Sony PlayStation.</p><ul><li>Оборудованная лаунж-зона: кулер, микроволновая печь, чайные принадлежности</li><li>Праздничная сервировка стола на всех гостей</li><li>Вся арена — ваша территория: играйте, побеждайте, не отвлекаясь на других</li></ul></div>`:tariffTable()}<p class="pricing-note">${icon('info')}Оборудование и инструктаж включены. ${event?'Праздник можно обсудить с администратором.':'«Игра» — стоимость за одного игрока. Остальные форматы — за компанию до 10 игроков.'}</p></div></section>`}
function pricesHero(){return `<section class="prices-hero"><div class="wrap"><nav class="breadcrumbs" aria-label="Хлебные крошки"><a href="/">Главная</a><span>/</span><span aria-current="page">Цены</span></nav><h1>ТВОЙ ФОРМАТ<br><em>ТВОЯ ИГРА</em></h1><p>Все цены в одной таблице. Выбери формат и удобное время.</p><a class="btn" href="#prices">Посмотреть цены</a></div></section>`}
function stepsSection(){return `<section class="section steps-section"><div class="wrap"><div class="section-head"><h2>КАК <em>ПОИГРАТЬ</em></h2></div><div class="steps"><div class="step"><span class="step-number">01</span><h3>Выбери формат и время</h3><p>Запишись в форме ниже. Можно прийти одному или компанией до 10 игроков.</p></div><div class="step"><span class="step-number">02</span><h3>Приходи за 15 минут</h3><p>Инструктор подберёт игру, настроит шлем и объяснит правила.</p></div><div class="step"><span class="step-number">03</span><h3>Играй и отдыхай</h3><p>Все настройки на нас. В праздничных пакетах есть лаунж-зона.</p></div></div></div></section>`}
const demoReviews=[{name:'Алексей',kind:'Игра с друзьями',text:'Первый раз играли всей компанией. Сначала осваивались, а через пять минут уже прикрывали друг друга и строили планы на следующий раунд.'},{name:'Мария',kind:'День рождения',text:'Дети обсуждали игру весь вечер. Успели и побегать по виртуальному миру, и спокойно посидеть с тортом. Очень необычный формат праздника.'},{name:'Дмитрий',kind:'Корпоратив',text:'Собрали две команды из коллег. Оказалось, что за пределами офиса мы отлично дополняем друг друга. Финал турнира был особенно азартным.'}];
function reviewHTML(r,demo=true){return `<article class="review"><div class="review-top"><span class="stars" aria-label="5 из 5">${icon('star').repeat(5)}</span><span>${demo?'ПРИМЕР ОТЗЫВА':'ЛОКАЛЬНЫЙ ОТЗЫВ'}</span></div><blockquote>${esc(r.text)}</blockquote><div class="review-person"><span class="avatar">${esc(r.name.slice(0,1))}</span><div>${esc(r.name)}<small>${esc(r.kind||'Посещение арены')}</small></div></div></article>`}
function reviewsSection(){return `<section class="section reviews-section" id="reviews"><div class="wrap reviews-invite"><div><div class="eyebrow">После снятого шлема</div><h2>ЭМОЦИИ <em>ОСТАЮТСЯ</em></h2><p>Истории арены, новости и впечатления гостей — в нашем сообществе.</p></div><a class="btn btn-outline" href="${vkCommunity}" target="_blank" rel="noopener noreferrer">Мы ВКонтакте ${icon('arrow')}</a></div></section>`;}
function faqSection(kind='home'){return `<section class="section" id="faq"><div class="wrap faq-inner"><div class="faq-copy"><div class="eyebrow">Перед погружением</div><h2>ЕСТЬ ВОПРОСЫ?<br><em>ЕСТЬ ОТВЕТЫ</em></h2><p>Всё, что нужно знать перед первым визитом. А с остальным поможет администратор.</p><button class="text-link" style="background:none;border-width:0 0 1px" data-action="callback">Задать свой вопрос ${icon('arrow')}</button></div><div class="faq-list">${faq.map(([q,a],i)=>`<details${i===0?' open':''}><summary>${q}<span class="faq-toggle">${icon('plus')}${icon('minus')}</span></summary><p>${a}</p></details>`).join('')}</div></div></section>`}
function blogSection(){return `<section class="section blog-section" id="blog"><div class="wrap"><div class="eyebrow">По ту сторону привычного</div><div class="section-head"><h2>НОВОСТИ <em>ЗА ГРАНЬЮ</em></h2></div><div class="blog-grid">${articles.map((a,i)=>`<button class="blog-card" data-action="article" data-index="${i}"><div class="blog-visual"><img src="/assets/${a.image}" alt="${esc(a.title)}" loading="lazy" width="600" height="300"><span class="tag">${a.category}</span></div><span class="blog-date">${a.date}</span><h3>${a.title} ${icon('arrow')}</h3></button>`).join('')}</div></div></section>`}
function contacts(){return `<section class="contact-section" id="contacts"><div class="wrap contact-inner"><div class="contact-copy"><div class="eyebrow">Приходи на арену</div><h2>МЫ <em>РЯДОМ</em></h2><div class="contact-info"><div><small>Адрес</small><p>Барнаул, проспект Красноармейский, 51а<br>ТЦ «Гулливер»</p></div><div><small>Телефон</small><a href="tel:${venuePhone}">${venuePhoneLabel}</a></div><div><small>Время работы</small><p>Ежедневно с 10:00 до 22:00</p></div></div>${socialLinks('contact-socials')}</div><div class="yandex-map"><div class="yandex-map-heading">${icon('pin')}<div><strong>Как нас найти</strong><p>Красноармейский, 51а · ТЦ «Гулливер»</p></div></div><iframe src="${esc(venueMapEmbed)}" title="Яндекс Карты — ${esc(venueAddress)}" loading="lazy" allowfullscreen referrerpolicy="no-referrer-when-downgrade"></iframe><div class="yandex-map-footer"><span>Барнаул · ТЦ «Гулливер»</span><a class="text-link" href="${venueMapUrl}" target="_blank" rel="noopener noreferrer">Открыть карту</a></div></div></div></section>`}
function innerHero(kind){const birth=kind==='birthday';return `<section class="hero inner-hero ${birth?'birthday':'corporate'}"><div class="hero-art"${config[kind]?` style="background-image:url('/assets/${esc(config[kind])}')"`:''}></div><div class="wrap hero-inner"><nav class="breadcrumbs" aria-label="Хлебные крошки"><a href="/">Главная</a><span>/</span><a href="/#events">Мероприятия</a><span>/</span><span aria-current="page">${birth?'Дни рождения':'Корпоративы'}</span></nav><div class="eyebrow">${birth?'Твой день — твои правила':'Из коллег — в команду героев'}</div><h1>${birth?'ДЕНЬ РОЖДЕНИЯ<br>ЗА ГРАНЬЮ<span>ПРИВЫЧНОГО</span>':'ВМЕСТЕ<br>В ДРУГОЙ<span>РЕАЛЬНОСТИ</span>'}</h1><p class="hero-sub">${birth?'Командный опыт. Выбирайте миссии, побеждайте вместе, поддерживайте друг друга, создавайте общие воспоминания':'Оставьте рабочие задачи за дверью. Здесь вас ждут командная миссия, азарт турнира и эмоции, которые объединяют'}</p><div class="hero-actions"><button class="btn" data-book data-format="${kind}" data-duration="120">${birth?'Спланировать праздник':'Собрать команду'} ${icon('arrow')}</button><a class="btn btn-outline" href="#prices">Посмотреть пакеты</a></div><div class="hero-badges"><span>${icon('users')} ${birth?'От 7+ и старше':'Для команд от 2 человек'}</span><span>${icon('coffee')} Своя лаунж-зона${birth?' (чай, кофе, посуда)':''}</span><span>${icon('shield')} Всегда рядом инструктор</span>${birth?`<span>${icon('users')} От 2 до 10 человек</span>`:''}</div></div></section>`}
function included(kind){const birth=kind==='birthday';const items=birth?[
 ['headset','Праздник внутри игры','Командные миссии под возраст и интересы гостей.','birthday/game-party.webp',941,1672],['users','Вся компания вместе','До 10 игроков, арена только для вас.','birthday/all-together.webp',1024,1536],['coffee','Лаунж-зона','Можно принести торт и еду. Сервировку подготовим.','birthday/lounge.webp',1024,1536],['shield','Инструктор рядом','Покажет управление и поможет во время игры.','birthday/instructor.webp',941,1672]
 ]:[['trophy','Командный турнир','Несколько раундов и общая цель.'],['move','Игра вместе','Договаривайтесь и побеждайте командой.'],['coffee','Время для общения','После игры отдохните в лаунж-зоне.'],['shield','Организация на нас','Инструктаж, оборудование и подбор игр.']];return `<section class="section"><div class="wrap"><div class="section-head"><h2>${birth?'ПРАЗДНИК <em>ДЛЯ ВСЕХ</em>':'ВМЕСТЕ В ДРУГОЙ <em>РЕАЛЬНОСТИ</em>'}</h2></div><div class="included-grid ${birth?'included-photos':''}">${items.map(([i,h,p,image,imageWidth,imageHeight])=>`<div class="included">${image?`<img src="/assets/${image}" srcset="/assets/${image.replace('.webp','-450.webp')} 450w, /assets/${image} 900w" sizes="(max-width: 640px) calc(100vw - 40px), (max-width: 850px) calc((100vw - 70px) / 2), calc((100vw - 138px) / 4)" alt="${h}" loading="lazy" decoding="async" width="${imageWidth}" height="${imageHeight}">`:icon(i)}<h3>${h}</h3><p>${p}</p></div>`).join('')}</div></div></section>`}
function schedule(kind){const birth=kind==='birthday';const items=[['00:00','Знакомимся с ареной','Встречаем гостей, показываем игровую и лаунж-зоны.'],['00:15','Готовимся к игре','Выбираем сценарий, настраиваем шлемы и тренируемся.'],['00:30','Играем вместе','Проходим миссии, меняем карты и команды.'],['01:30',birth?'Торт и подарки':'Время для общения',birth?'Отдыхаем в лаунж-зоне и делаем общее фото.':'Делимся впечатлениями в лаунж-зоне.']];return `<section class="section schedule-section"><div class="wrap"><div class="eyebrow">Пример программы на 2 часа</div><div class="section-head"><h2>ТАК ПРОХОДИТ <em>${birth?'ТВОЙ ДЕНЬ':'ВАШ КОРПОРАТИВ'}</em></h2></div><div class="timeline">${items.map(([t,h,p])=>`<div class="timeline-item"><small>${t}</small><h3>${h}</h3><p>${p}</p></div>`).join('')}</div><button class="btn schedule-contact" data-action="callback">Обсудить мероприятие</button></div></section>`}
function admin(){const list=readStore(key,[]);return `<section class="admin-page"><div class="wrap"><nav class="breadcrumbs"><a href="/">Главная</a><span>/</span><span aria-current="page">Демо-админка</span></nav><div class="eyebrow">Тестовый режим</div><h1>ЗАЯВКИ И НАСТРОЙКИ</h1><p class="muted small">Данные хранятся только в этом браузере. Это открытый демонстрационный интерфейс, который не предназначен для реальных персональных данных. Серверная база, авторизация и email-уведомления не подключены.</p><div class="admin-tools"><button class="btn btn-outline" data-action="export">Выгрузить JSON ${icon('arrow')}</button><button class="btn btn-outline" data-action="clear-requests">Очистить демо-заявки</button></div><div class="admin-table-wrap">${list.length?`<table class="admin-table"><thead><tr><th>Номер / дата</th><th>Тип / контакт</th><th>Детали</th><th>Статус</th></tr></thead><tbody>${list.slice().reverse().map(r=>`<tr><td>${esc(r.id)}<small>${new Date(r.created).toLocaleString('ru-RU',{timeZone:'Asia/Barnaul'})}</small></td><td>${esc(r.type)}<small>${esc(r.name)} · ${esc(r.phone||r.email||'')}</small></td><td>${r.format?esc(formatName(r.format))+'<small>'+esc(r.date)+' · '+esc(r.time)+' · '+esc(r.players)+' чел. · '+esc(r.duration)+' мин.</small>':''}<small>${esc(r.message||r.game||r.package||'—')}</small></td><td><select aria-label="Статус заявки ${esc(r.id)}" data-status="${esc(r.id)}">${['Новая','В работе','Завершена'].map(s=>`<option${r.status===s?' selected':''}>${s}</option>`).join('')}</select></td></tr>`).join('')}</tbody></table>`:'<p class="admin-empty">Заявок пока нет. Заполни демо-форму записи, чтобы увидеть её здесь.</p>'}</div><form class="admin-config" id="config-form"><h2>Фоны страниц</h2><p class="muted small" style="margin-bottom:20px">Изменения видны только в этом браузере. Используются изображения из ваших референсов.</p><div class="form-grid">${[['home','Главная'],['birthday','Дни рождения'],['corporate','Корпоративы']].map(([k,label])=>`<label class="field"><span>${label}</span><select name="${k}">${[['','По умолчанию'],['hero.webp','VR-боец / синий'],['battle.webp','VR-команда'],['events.webp','Праздники'],['arena.webp','Интерьер арены'],['pattern.webp','Геометрия']].map(([v,l])=>`<option value="${v}"${config[k]===v?' selected':''}>${l}</option>`).join('')}</select></label>`).join('')}</div><button class="btn" type="submit">Сохранить фоны ${icon('check')}</button></form></div></section>`}
function promoLauncher(){return `<button class="promo-tab" data-action="wheel" aria-label="Открыть колесо скидок" aria-haspopup="dialog" aria-controls="modal-root" aria-expanded="false"><span class="promo-tab-art" aria-hidden="true">${icon('gift')}</span><span class="promo-tab-title">Твоя скидка</span><span class="promo-tab-arrow" aria-hidden="true">${icon('left')}</span></button>`}
function render(){document.title=page==='birthday'?'Дни рождения — За Гранью':page==='corporate'?'Корпоративы — За Гранью':page==='prices'?'Цены — За Гранью':'За Гранью — VR-арена';let content=page==='home'?homeHero()+eventsSection()+gamesSection()+pricing()+bookingSection()+stepsSection()+contacts()+faqSection():page==='prices'?pricesHero()+pricing()+contacts()+bookingSection():page==='admin'?admin():innerHero(page)+included(page)+pricing(page)+bookingSection()+schedule(page)+faqSection(page)+contacts();$('#app').innerHTML=header()+`<main id="main">${content}</main>`+footer()+(page==='admin'?'':promoLauncher()+mobileActions());if($('#booking-form')){syncDurations();setBookingDate();updateEstimate();}}
render();
let lastFocus=null,slide=0,storyIndex=0,toastTimer,wheelTimer;
function toast(message){clearTimeout(toastTimer);$('#toast').textContent=message;$('#toast').classList.add('show');toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),4500)}
function modal(content,cls=''){if(!$('#modal-root').hasChildNodes())lastFocus=document.activeElement;$('#modal-root').innerHTML=`<div class="modal-overlay"><section class="modal ${cls}" role="dialog" aria-modal="true" aria-labelledby="modal-title"><button class="icon-btn modal-close" data-action="close" aria-label="Закрыть окно">${icon('close')}</button>${content}</section></div>`;document.body.classList.add('locked');requestAnimationFrame(()=>$('.modal-close')?.focus());}
function closeModal(){$('.promo-tab')?.setAttribute('aria-expanded','false');clearTimeout(wheelTimer);$('#modal-root').innerHTML='';if(!$('.mobile-nav.open'))document.body.classList.remove('locked');lastFocus?.focus();}
function formatName(v){return {game:'Игра',private:'Закрытая арена',birthday:'День рождения',corporate:'Корпоратив'}[v]||v}
function consent(){return `<label class="consent"><input type="checkbox" name="consent" required><span>Согласен с <button type="button" data-action="privacy-note">условиями демо-формы</button>. Не указываю реальные персональные данные.</span></label>`}
function demoNote(){return `<div class="demo-note"><b>Демонстрационная запись.</b> Заявка сохранится в этом браузере. Сеанс не резервируется, звонка, оплаты и отправки письма не будет.</div>`}
function bookingForm(opts={}){if(window.ZGBooking?.enabled)return window.ZGBooking.form(opts);return `<div class="booking-server-link"><h3>Выбери свободный сеанс</h3><p>Актуальное расписание и онлайн-запись доступны на сайте арены.</p><a class="btn" href="https://za-granyu22.ru/#booking">Перейти к записи ${icon('arrow')}</a></div>`;}
function bookingSection(){const opts=['birthday','corporate'].includes(page)?{format:page,duration:'120'}:{};return `<section class="section booking-section" id="booking" tabindex="-1" aria-labelledby="booking-title"><div class="wrap"><div class="section-head"><div><div class="eyebrow">Онлайн-запись</div><h2 id="booking-title">ВЫБЕРИ ВРЕМЯ<br><em>И ЗАБРОНИРУЙ ИГРУ</em></h2></div><p class="booking-intro">Свободное время из расписания арены. <br>Игру поможем выбрать на месте.</p></div><div class="booking-panel">${bookingForm(opts)}</div></div></section>`}
function booking(opts={}){
 const section=$('#booking');
 if(section&&window.ZGBooking?.enabled){
  if(opts.format||opts.package){$('.booknow-form',section)?.dispatchEvent(new CustomEvent('zg:select-format',{detail:opts}));}
  section.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth',block:'start'});
  section.focus({preventScroll:true});
  return;
 }
 if(window.ZGBooking?.enabled){window.ZGBooking.open(opts);return;}
 location.assign('https://za-granyu22.ru/#booking');
}
function setBookingDate(day){const form=$('#booking-form');if(!form)return;let date=new Date(today()+'T12:00:00');const hour=Number(new Intl.DateTimeFormat('en-GB',{timeZone:'Asia/Barnaul',hour:'2-digit',hour12:false}).format(new Date()));if(hour>=20)date.setDate(date.getDate()+1);if(day){for(let i=0;i<7;i++){const isWeekend=[0,5,6].includes(date.getDay());if((day==='weekend')===isWeekend)break;date.setDate(date.getDate()+1);}}const value=date.getFullYear()+'-'+String(date.getMonth()+1).padStart(2,'0')+'-'+String(date.getDate()).padStart(2,'0');$('[name=date]',form).value=value;if(value===today())$('[name=time]',form).value=String(Math.max(10,Math.min(20,hour+1))).padStart(2,'0')+':00';}
function durationChoices(format){return ['birthday','corporate','private'].includes(format)?[['60','1 час'],['120','2 часа'],['180','3 часа']]:[['60','60 минут']]}
function syncDurations(preferred){const form=$('#booking-form');if(!form)return;const format=$('[name=format]:checked',form).value;const select=$('[name=duration]',form);const selected=String(preferred||select.value||60);const options=durationChoices(format);select.innerHTML=options.map(([v,t])=>`<option value="${v}">${t}</option>`).join('');select.value=options.some(([v])=>v===selected)?selected:options[0][0];}
function estimate(data){const isWeekend=[0,5,6].includes(new Date(data.date+'T12:00:00').getDay());const rateIndex=isWeekend?1:0;if(data.format==='game')return gameRates[rateIndex]*Number(data.players);if(data.format==='private')return privatePackageRates[data.duration]?.[rateIndex]??null;return eventRates[data.duration]?.[rateIndex]??null}
function updateEstimate(){const form=$('#booking-form');if(!form)return;const data=Object.fromEntries(new FormData(form));const price=estimate(data);$('#booking-estimate').textContent=price===null?'Уточните у администратора':money(price);$('#booking-estimate').classList.toggle('estimate-unconfirmed',price===null);$('#estimate-unit').textContent=data.format==='game'?'· за всех игроков':'· за компанию';const end=Number(data.time.split(':')[0])+Number(data.duration)/60;const time=$('[name=time]',form);time.setCustomValidity(end>22?'Сеанс должен закончиться до 22:00. Выберите более раннее время.':'');const game=games.find(g=>g.id===data.game);const count=Number(data.players);const max=game?Number(game.players.match(/–(\d+)/)?.[1]||10):10;const min=game&&game.category==='team'?2:1;const player=$('[name=players]',form);player.setCustomValidity(count>max||count<min?`Для этой игры нужно от ${min} до ${max} игроков.`:'');$('#booking-availability').textContent=end>22?'Выберите более раннее время: арена работает до 22:00.':count>max||count<min?`Для сценария «${game.title}» нужно от ${min} до ${max} игроков.`:price===null?'Цена часового праздника в ПТ–ВС уточняется у администратора.':'Сеансы и доступность показаны для примера.';}

function saveRequest(data){const list=readStore(key,[]);const random=globalThis.crypto?.randomUUID?.().slice(0,8).toUpperCase()||Math.random().toString(36).slice(2,10).toUpperCase();const r={...data,id:'ЗГ-'+random,created:new Date().toISOString(),status:'Новая'};if(!writeStore(key,[...list,r]))return null;return r;}
function success(r,type='заявка'){modal(`<div class="success"><div class="success-icon">${icon('check')}</div><div class="eyebrow" style="justify-content:center">Демо-режим</div><h2 id="modal-title">${type==='отзыв'?'ОТЗЫВ':'ЗАЯВКА'} <span class="blue">СОХРАНЁН${type==='отзыв'?'':'А'}.</span></h2><div class="reference">${esc(r.id)}</div><p>${type==='отзыв'?'Отзыв сохранён локально в этом браузере.':'Это тестовая заявка. Время не забронировано, администратор не получит уведомление и не будет звонить.'}</p><p>Посмотреть сохранённые данные можно в <a href="/admin/" style="color:var(--blue);text-decoration:underline">демо-админке</a>.</p><button class="btn btn-outline" data-action="close">Вернуться на сайт ${icon('arrow')}</button></div>`);}
function showStory(id){storyIndex=Math.max(0,games.findIndex(g=>g.id===id));const g=games[storyIndex];modal(`<div class="story-progress" role="group" aria-label="Обзоры игр">${games.map((x,i)=>`<button class="${i===storyIndex?'active':''}" data-action="story" data-id="${x.id}" aria-label="${esc(x.title)}" aria-pressed="${i===storyIndex}"></button>`).join('')}</div><div class="story-media">${g.video?`<video class="story-video" controls playsinline preload="none" poster="/assets/${g.image}" aria-label="Видеообзор ${g.title}"><source src="/assets/${g.video}" type="video/mp4">Ваш браузер не поддерживает видео</video>`:`${gameArtwork(g)}`}</div><div class="story-content"><span class="tag">${g.mode}${g.age?' · '+g.age:''}</span><h2 id="modal-title">${g.title}</h2><div class="game-meta"><span>${g.genre}</span><span>${g.players}</span></div><p>${g.description}</p><div class="story-footer"><button class="btn" data-book data-game="${g.id}" data-duration="60">Выбрать игру ${icon('arrow')}</button><button class="icon-btn" data-action="story-next" aria-label="Следующая игра">${icon('arrow')}</button></div></div>`,'story-modal');}

function callback(){modal(`<div class="eyebrow">На связи с тобой</div><h2 id="modal-title">ПОМОЖЕМ ВЫБРАТЬ</h2><p class="modal-intro">Расскажи о вашей компании — подберём игру и ответим на вопросы о празднике.</p><div class="contact-actions"><a class="btn" href="tel:${venuePhone}">Позвонить ${venuePhoneLabel} ${icon('phone')}</a>${socialLinks()}</div>`);}
function reviewModal(){modal(`<div class="eyebrow">После игры</div><h2 id="modal-title">ПОДЕЛИСЬ ВПЕЧАТЛЕНИЯМИ</h2><p class="modal-intro">Расскажи о посещении в нашем сообществе ВКонтакте. Нам важно, как прошла ваша игра.</p><a class="btn" href="${vkCommunity}" target="_blank" rel="noopener noreferrer">Открыть сообщество ${icon('arrow')}</a>`);}
function privacy(){document.querySelector('[data-privacy-link]')?.click();}
function wheel(){window.ZGPromo?.open();}
function article(i){const a=articles[i];if(!a)return;const body=a.blocks.map(block=>block.type==='ul'||block.type==='ol'?`<${block.type}>${block.items.map(item=>'<li>'+esc(item)+'</li>').join('')}</${block.type}>`:`<${block.type}>${esc(block.text)}</${block.type}>`).join('');modal(`<div class="eyebrow">${a.category} / Новости за гранью</div><h2 id="modal-title">${a.title}</h2><div class="article-body"><p class="muted">${a.date}</p><img src="/assets/${a.image}" alt="${esc(a.title)}">${body}<div class="article-actions"><button class="btn" data-book>Выбрать своё приключение ${icon('arrow')}</button><a class="btn btn-outline" href="${maxMessenger}" target="_blank" rel="noopener noreferrer">Написать в MAX</a><a class="text-link" href="tel:${venuePhone}">Позвонить ${venuePhoneLabel}</a></div></div>`,'article-modal');}
function heroSlide(dir){slide=(slide+Number(dir)+3)%3;const titles=['ВЫХОДИ<br>ЗА ГРАНЬ<span>РЕАЛЬНОГО</span>','ПРОВЕДИТЕ ПРАЗДНИК,<br>КОТОРЫЙ ВАШИ ГОСТИ<span>ТОЧНО ЗАПОМНЯТ</span>','НОВЫЙ МИР<br>НАСТОЯЩИЕ<span>ЭМОЦИИ</span>'];const subs=['<strong>НОВЫЙ ФОРМАТ КОМАНДНЫХ ИГР</strong><p>Играй один или компанией до 10 человек. От 7 лет. Всё покажет инструктор.</p>','VR-праздник в Барнауле для детей, взрослых, друзей, классов и компаний — с командными играми, лаунж-зоной','Окунись в мир виртуальной реальности на новой «безграничной» площадке'];$('.hero').dataset.slide=slide;$('#hero-title').innerHTML=titles[slide];$('#hero-sub').innerHTML=subs[slide];$('#slide-current').textContent='0'+(slide+1);document.dispatchEvent(new CustomEvent('zg:hero-slide'));}

function closeMenu(){const nav=$('.mobile-nav');nav?.classList.remove('open');const b=$('.menu-toggle');b?.setAttribute('aria-expanded','false');b?.setAttribute('aria-label','Открыть меню');if(!$('#modal-root').hasChildNodes())document.body.classList.remove('locked');}
document.addEventListener('click',e=>{
 const book=e.target.closest('[data-book]');if(book){closeMenu();booking({format:book.dataset.format,duration:book.dataset.duration,game:book.dataset.game,package:book.dataset.package,day:null});return;}
 const filter=e.target.closest('[data-filter]');if(filter){$$('[data-filter]').forEach(b=>{b.classList.toggle('active',b===filter);b.setAttribute('aria-pressed',String(b===filter))});$('#game-grid').innerHTML=games.filter(g=>filter.dataset.filter==='all'||g.category===filter.dataset.filter).map(gameCard).join('');return;}

 if(e.target.closest('.mobile-nav a'))closeMenu();
 if(e.target.classList.contains('modal-overlay')){closeModal();return;}
 const b=e.target.closest('[data-action]');if(!b)return;
 switch(b.dataset.action){
 case 'close':closeModal();break;
 case 'menu':{const open=$('.mobile-nav').classList.toggle('open');b.setAttribute('aria-expanded',String(open));b.setAttribute('aria-label',open?'Закрыть меню':'Открыть меню');document.body.classList.toggle('locked',open);break;}
 case 'story':showStory(b.dataset.id);break;
 case 'story-next':showStory(games[(storyIndex+1)%games.length].id);break;
 case 'slide':heroSlide(b.dataset.direction);break;
 case 'callback':callback();break;
 case 'review':reviewModal();break;
 case 'privacy':privacy();break;
 case 'privacy-note':toast('Демо-форма сохраняется только в этом браузере. Используйте вымышленные контакты.');break;
 case 'wheel':wheel();break;

 case 'article':article(Number(b.dataset.index));break;
 case 'social':toast('Это демонстрационная ссылка. Адрес сообщества пока не указан.');break;
 case 'export':{const blob=new Blob([JSON.stringify(readStore(key,[]),null,2)],{type:'application/json;charset=utf-8'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='za-granyu-demo-requests.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);break;}
 case 'clear-requests':modal(`<div class="eyebrow">Демо-админка</div><h2 id="modal-title">УДАЛИТЬ ДЕМО-ЗАЯВКИ?</h2><p class="modal-intro">Все заявки и отзывы, сохранённые в этом браузере, будут удалены.</p><div class="form-actions"><button class="btn btn-outline" data-action="close">Отмена</button><button class="btn" data-action="confirm-clear">Удалить</button></div>`);break;
 case 'confirm-clear':if(writeStore(key,[])){closeModal();render();toast('Демонстрационные заявки удалены.')}break;
 }
});
document.addEventListener('change',e=>{if(e.target.closest('#booking-form')){if(e.target.name==='format'){syncDurations();$('[name=package]',$('#booking-form')).value='';}if(e.target.name==='duration')$('[name=package]',$('#booking-form')).value='';updateEstimate();}if(e.target.matches('[data-status]')){const list=readStore(key,[]);const r=list.find(x=>x.id===e.target.dataset.status);if(r){r.status=e.target.value;if(writeStore(key,list))toast('Статус сохранён.');}}});
document.addEventListener('submit',e=>{
 if(e.target.id==='booking-form'){e.preventDefault();updateEstimate();if(!e.target.reportValidity())return;const d=Object.fromEntries(new FormData(e.target));const r=saveRequest({...d,type:'Запись',estimate:estimate(d),game:games.find(g=>g.id===d.game)?.title||'Подбор игры'});if(r){e.target.reset();syncDurations();setBookingDate();updateEstimate();success(r);}}
 if(e.target.id==='contact-form'){e.preventDefault();const d=Object.fromEntries(new FormData(e.target));const r=saveRequest({...d,type:'Обратная связь'});if(r)success(r);}
 if(e.target.id==='review-form'){e.preventDefault();const d=Object.fromEntries(new FormData(e.target));const r=saveRequest({...d,type:'Отзыв'});if(r){const grid=$('#review-grid');if(grid)grid.insertAdjacentHTML('afterbegin',reviewHTML({name:d.name,text:d.message,kind:d.kind},false));success(r,'отзыв');}}
 if(e.target.id==='config-form'){e.preventDefault();const d=Object.fromEntries(new FormData(e.target));if(writeStore('zg-demo-config',d)){Object.assign(config,d);toast('Фоны сохранены. Откройте нужную страницу.');}}
});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){if($('#modal-root').hasChildNodes())closeModal();else closeMenu();}if(e.key==='Tab'&&$('.modal')){const nodes=$$('button:not([disabled]),a[href],input,select,textarea,[tabindex="0"]',$('.modal')).filter(x=>x.offsetParent!==null);const first=nodes[0],last=nodes.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus();}}if(e.key==='ArrowRight'&&$('.story-modal'))showStory(games[(storyIndex+1)%games.length].id);if(e.key==='ArrowLeft'&&$('.story-modal'))showStory(games[(storyIndex+games.length-1)%games.length].id);});
window.addEventListener('resize',()=>{if(innerWidth>1000)closeMenu();});
if(location.hash)requestAnimationFrame(()=>$(location.hash)?.scrollIntoView());
